/**
 * Modular image preprocessors — Phase 2
 *
 * Each function is pure: (FrameBuffer, options?) → FrameBuffer
 * Grayscale output uses format: 'gray' (1 byte/pixel) for later stages.
 */

import type {
  BrightnessOptions,
  ContrastOptions,
  DenoiseOptions,
  FrameBuffer,
  ResizeOptions,
  ROI,
  SharpenOptions,
  ThresholdOptions,
} from './types';

function ensureRgba(frame: FrameBuffer): FrameBuffer {
  if (frame.format === 'rgba') return frame;
  // Expand gray → rgba
  const rgba = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let i = 0, j = 0; i < frame.data.length; i++, j += 4) {
    const v = frame.data[i]!;
    rgba[j] = v;
    rgba[j + 1] = v;
    rgba[j + 2] = v;
    rgba[j + 3] = 255;
  }
  return {
    width: frame.width,
    height: frame.height,
    format: 'rgba',
    data: rgba,
    timestamp: frame.timestamp,
  };
}

function ensureGray(frame: FrameBuffer): FrameBuffer {
  if (frame.format === 'gray') return frame;
  return grayscale(frame);
}

/** ITU-R BT.601 luma */
export function grayscale(frame: FrameBuffer): FrameBuffer {
  if (frame.format === 'gray') {
    return {
      ...frame,
      data: new Uint8ClampedArray(frame.data),
    };
  }
  const src = frame.data;
  const out = new Uint8ClampedArray(frame.width * frame.height);
  for (let i = 0, p = 0; i < src.length; i += 4, p++) {
    const r = src[i]!;
    const g = src[i + 1]!;
    const b = src[i + 2]!;
    out[p] = (r * 77 + g * 150 + b * 29) >> 8;
  }
  return {
    width: frame.width,
    height: frame.height,
    format: 'gray',
    data: out,
    timestamp: frame.timestamp,
  };
}

export function contrast(frame: FrameBuffer, options: ContrastOptions = { factor: 1.4 }): FrameBuffer {
  const factor = options.factor;
  if (frame.format === 'gray') {
    const out = new Uint8ClampedArray(frame.data.length);
    for (let i = 0; i < frame.data.length; i++) {
      out[i] = clamp(Math.round((frame.data[i]! - 128) * factor + 128));
    }
    return { ...frame, data: out };
  }
  const src = frame.data;
  const out = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    out[i] = clamp(Math.round((src[i]! - 128) * factor + 128));
    out[i + 1] = clamp(Math.round((src[i + 1]! - 128) * factor + 128));
    out[i + 2] = clamp(Math.round((src[i + 2]! - 128) * factor + 128));
    out[i + 3] = src[i + 3]!;
  }
  return { ...frame, data: out };
}

export function brightness(
  frame: FrameBuffer,
  options: BrightnessOptions = { amount: 20 }
): FrameBuffer {
  const amount = options.amount;
  if (frame.format === 'gray') {
    const out = new Uint8ClampedArray(frame.data.length);
    for (let i = 0; i < frame.data.length; i++) {
      out[i] = clamp(frame.data[i]! + amount);
    }
    return { ...frame, data: out };
  }
  const src = frame.data;
  const out = new Uint8ClampedArray(src.length);
  for (let i = 0; i < src.length; i += 4) {
    out[i] = clamp(src[i]! + amount);
    out[i + 1] = clamp(src[i + 1]! + amount);
    out[i + 2] = clamp(src[i + 2]! + amount);
    out[i + 3] = src[i + 3]!;
  }
  return { ...frame, data: out };
}

/**
 * Simple unsharp-mask style sharpen on grayscale (or after converting).
 * Kernel approximation: center = 1+4a, neighbors = -a
 */
export function sharpen(frame: FrameBuffer, options: SharpenOptions = { amount: 0.6 }): FrameBuffer {
  const gray = ensureGray(frame);
  const w = gray.width;
  const h = gray.height;
  const src = gray.data;
  const out = new Uint8ClampedArray(src.length);
  const a = options.amount;
  const center = 1 + 4 * a;

  // Copy borders
  out.set(src);

  for (let y = 1; y < h - 1; y++) {
    for (let x = 1; x < w - 1; x++) {
      const i = y * w + x;
      const v =
        center * src[i]! -
        a * src[i - 1]! -
        a * src[i + 1]! -
        a * src[i - w]! -
        a * src[i + w]!;
      out[i] = clamp(Math.round(v));
    }
  }

  return {
    width: w,
    height: h,
    format: 'gray',
    data: out,
    timestamp: frame.timestamp,
  };
}

export function threshold(
  frame: FrameBuffer,
  options: ThresholdOptions = { value: 128 }
): FrameBuffer {
  const gray = ensureGray(frame);
  const t = options.value;
  const out = new Uint8ClampedArray(gray.data.length);
  for (let i = 0; i < gray.data.length; i++) {
    out[i] = gray.data[i]! >= t ? 255 : 0;
  }
  return {
    width: gray.width,
    height: gray.height,
    format: 'gray',
    data: out,
    timestamp: frame.timestamp,
  };
}

/** Simple box-filter denoise on grayscale */
export function denoise(frame: FrameBuffer, options: DenoiseOptions = { radius: 1 }): FrameBuffer {
  const gray = ensureGray(frame);
  const r = Math.max(1, Math.min(3, Math.floor(options.radius)));
  const w = gray.width;
  const h = gray.height;
  const src = gray.data;
  const out = new Uint8ClampedArray(src.length);
  const area = (2 * r + 1) * (2 * r + 1);

  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      let sum = 0;
      for (let dy = -r; dy <= r; dy++) {
        const yy = Math.min(h - 1, Math.max(0, y + dy));
        for (let dx = -r; dx <= r; dx++) {
          const xx = Math.min(w - 1, Math.max(0, x + dx));
          sum += src[yy * w + xx]!;
        }
      }
      out[y * w + x] = Math.round(sum / area);
    }
  }

  return {
    width: w,
    height: h,
    format: 'gray',
    data: out,
    timestamp: frame.timestamp,
  };
}

/**
 * Nearest-neighbor resize (fast, good enough for Phase 2 benchmark).
 * Works on gray or rgba.
 */
export function resize(frame: FrameBuffer, options: ResizeOptions): FrameBuffer {
  const dw = Math.max(1, Math.floor(options.width));
  const dh = Math.max(1, Math.floor(options.height));
  const sw = frame.width;
  const sh = frame.height;

  if (frame.format === 'gray') {
    const out = new Uint8ClampedArray(dw * dh);
    for (let y = 0; y < dh; y++) {
      const sy = Math.min(sh - 1, Math.floor((y * sh) / dh));
      for (let x = 0; x < dw; x++) {
        const sx = Math.min(sw - 1, Math.floor((x * sw) / dw));
        out[y * dw + x] = frame.data[sy * sw + sx]!;
      }
    }
    return {
      width: dw,
      height: dh,
      format: 'gray',
      data: out,
      timestamp: frame.timestamp,
    };
  }

  const src = ensureRgba(frame).data;
  const out = new Uint8ClampedArray(dw * dh * 4);
  for (let y = 0; y < dh; y++) {
    const sy = Math.min(sh - 1, Math.floor((y * sh) / dh));
    for (let x = 0; x < dw; x++) {
      const sx = Math.min(sw - 1, Math.floor((x * sw) / dw));
      const si = (sy * sw + sx) * 4;
      const di = (y * dw + x) * 4;
      out[di] = src[si]!;
      out[di + 1] = src[si + 1]!;
      out[di + 2] = src[si + 2]!;
      out[di + 3] = src[si + 3]!;
    }
  }
  return {
    width: dw,
    height: dh,
    format: 'rgba',
    data: out,
    timestamp: frame.timestamp,
  };
}

/** Crop ROI from an existing buffer (pixel coordinates of the buffer). */
export function crop(frame: FrameBuffer, roi: ROI): FrameBuffer {
  const x = Math.max(0, Math.floor(roi.x));
  const y = Math.max(0, Math.floor(roi.y));
  const w = Math.min(frame.width - x, Math.floor(roi.width));
  const h = Math.min(frame.height - y, Math.floor(roi.height));
  if (w <= 0 || h <= 0) {
    throw new Error('Invalid crop ROI');
  }

  if (frame.format === 'gray') {
    const out = new Uint8ClampedArray(w * h);
    for (let row = 0; row < h; row++) {
      const srcStart = (y + row) * frame.width + x;
      out.set(frame.data.subarray(srcStart, srcStart + w), row * w);
    }
    return {
      width: w,
      height: h,
      format: 'gray',
      data: out,
      timestamp: frame.timestamp,
    };
  }

  const src = frame.data;
  const out = new Uint8ClampedArray(w * h * 4);
  for (let row = 0; row < h; row++) {
    const srcStart = ((y + row) * frame.width + x) * 4;
    out.set(src.subarray(srcStart, srcStart + w * 4), row * w * 4);
  }
  return {
    width: w,
    height: h,
    format: 'rgba',
    data: out,
    timestamp: frame.timestamp,
  };
}

function clamp(v: number): number {
  return v < 0 ? 0 : v > 255 ? 255 : v;
}
