/**
 * CameraEngine — Phase 1
 *
 * Responsible for:
 * - Enumerating cameras
 * - Requesting permission via getUserMedia
 * - Selecting back / front / specific device
 * - Applying resolution & frame-rate constraints
 * - Detecting device capabilities
 * - Proper start / stop / switch / error handling
 *
 * No barcode processing here.
 */

import type {
  CameraCapabilities,
  CameraConstraints,
  CameraDeviceInfo,
  CameraError,
  CameraErrorCode,
  CameraFacingMode,
  CameraResolution,
  CameraState,
} from '../types';
import { logger } from '../utils/logger';

export type CameraEngineEvents = {
  statechange: (state: CameraState) => void;
  error: (error: CameraError) => void;
  trackended: () => void;
};

type EventHandlerMap = {
  [K in keyof CameraEngineEvents]: Set<CameraEngineEvents[K]>;
};

export class CameraEngine {
  private stream: MediaStream | null = null;
  private videoTrack: MediaStreamTrack | null = null;
  private state: CameraState = 'idle';
  private currentDeviceId: string | null = null;
  private handlers: EventHandlerMap = {
    statechange: new Set(),
    error: new Set(),
    trackended: new Set(),
  };

  /** Current MediaStream (null when inactive) */
  get mediaStream(): MediaStream | null {
    return this.stream;
  }

  /** Current video track */
  get track(): MediaStreamTrack | null {
    return this.videoTrack;
  }

  get currentState(): CameraState {
    return this.state;
  }

  get activeDeviceId(): string | null {
    return this.currentDeviceId;
  }

  // ─── Events ───────────────────────────────────────────────

  on<K extends keyof CameraEngineEvents>(event: K, handler: CameraEngineEvents[K]): () => void {
    this.handlers[event].add(handler);
    return () => this.handlers[event].delete(handler);
  }

  private emit<K extends keyof CameraEngineEvents>(
    event: K,
    ...args: Parameters<CameraEngineEvents[K]>
  ): void {
    for (const h of this.handlers[event]) {
      try {
        // @ts-expect-error – spread is correct for our map
        h(...args);
      } catch (e) {
        logger.error('Event handler error', e);
      }
    }
  }

  private setState(next: CameraState): void {
    if (this.state === next) return;
    this.state = next;
    this.emit('statechange', next);
  }

  // ─── Static helpers ───────────────────────────────────────

  /**
   * Check if the environment can use getUserMedia.
   *
   * Note: On many browsers (including Samsung Internet / Chrome),
   * `navigator.mediaDevices` is undefined when the page is NOT a
   * secure context (HTTP outside localhost). That must not be
   * reported as "browser does not support camera".
   */
  static isSupported(): boolean {
    if (typeof navigator === 'undefined') return false;

    // Modern API
    if (
      navigator.mediaDevices &&
      typeof navigator.mediaDevices.getUserMedia === 'function'
    ) {
      return true;
    }

    // Legacy prefixed APIs (very old WebViews; kept for completeness)
    const nav = navigator as Navigator & {
      getUserMedia?: unknown;
      webkitGetUserMedia?: unknown;
      mozGetUserMedia?: unknown;
    };
    if (
      typeof nav.getUserMedia === 'function' ||
      typeof nav.webkitGetUserMedia === 'function' ||
      typeof nav.mozGetUserMedia === 'function'
    ) {
      return true;
    }

    // mediaDevices missing is often caused by insecure context, not lack of support
    // Treat as "supported but blocked" only when we can detect insecure context
    return false;
  }

  /** Check secure context (required for camera on almost all browsers) */
  static isSecureContext(): boolean {
    if (typeof window === 'undefined') return false;
    // window.isSecureContext is the authoritative signal
    if (typeof window.isSecureContext === 'boolean') {
      return window.isSecureContext;
    }
    // Fallback heuristic
    const proto = window.location?.protocol;
    const host = window.location?.hostname;
    return (
      proto === 'https:' ||
      host === 'localhost' ||
      host === '127.0.0.1' ||
      host === '[::1]'
    );
  }

  /**
   * Diagnostic snapshot for debugging browser / context issues.
   * Useful on Samsung Internet, older WebViews, etc.
   */
  static getEnvironmentInfo(): {
    supported: boolean;
    secureContext: boolean;
    hasMediaDevices: boolean;
    hasGetUserMedia: boolean;
    protocol: string;
    hostname: string;
    userAgent: string;
  } {
    const hasMediaDevices = !!(
      typeof navigator !== 'undefined' && navigator.mediaDevices
    );
    const hasGetUserMedia = !!(
      hasMediaDevices &&
      typeof navigator.mediaDevices.getUserMedia === 'function'
    );
    return {
      supported: CameraEngine.isSupported(),
      secureContext: CameraEngine.isSecureContext(),
      hasMediaDevices,
      hasGetUserMedia,
      protocol: typeof location !== 'undefined' ? location.protocol : '',
      hostname: typeof location !== 'undefined' ? location.hostname : '',
      userAgent: typeof navigator !== 'undefined' ? navigator.userAgent : '',
    };
  }

  /** Build a clear error when camera cannot be used */
  private static buildUnavailableError(): CameraError {
    const info = CameraEngine.getEnvironmentInfo();

    // Most common real-world cause on mobile: opened via http://LAN-IP
    if (!info.secureContext) {
      return {
        code: 'SecurityError',
        message:
          'Camera requires a secure context (HTTPS or localhost). ' +
          `Current origin is ${info.protocol}//${info.hostname}. ` +
          'On Samsung Internet / Chrome, navigator.mediaDevices is hidden on insecure pages. ' +
          'Serve the app over HTTPS or open it from localhost.',
      };
    }

    if (!info.hasMediaDevices || !info.hasGetUserMedia) {
      return {
        code: 'NotFoundError',
        message:
          'getUserMedia is not available in this browser/context. ' +
          `UA: ${info.userAgent.slice(0, 80)}…`,
      };
    }

    return {
      code: 'NotFoundError',
      message: 'Camera API is not available',
    };
  }

  // ─── Device enumeration ───────────────────────────────────

  /**
   * List available video input devices.
   * Requires prior permission for meaningful labels on most browsers.
   */
  async listDevices(): Promise<CameraDeviceInfo[]> {
    if (!CameraEngine.isSupported()) {
      throw CameraEngine.buildUnavailableError();
    }

    const devices = await navigator.mediaDevices.enumerateDevices();
    const videoInputs = devices.filter((d) => d.kind === 'videoinput');

    return videoInputs.map((d) => {
      const facing = this.inferFacingMode(d.label, d.deviceId);
      return {
        deviceId: d.deviceId,
        label: d.label || `Camera ${d.deviceId.slice(0, 8)}`,
        facingMode: facing,
        groupId: d.groupId,
      };
    });
  }

  private inferFacingMode(label: string, _deviceId: string): CameraFacingMode | undefined {
    const lower = label.toLowerCase();
    if (
      lower.includes('back') ||
      lower.includes('rear') ||
      lower.includes('environment') ||
      lower.includes('world')
    ) {
      return 'environment';
    }
    if (
      lower.includes('front') ||
      lower.includes('user') ||
      lower.includes('face') ||
      lower.includes('selfie')
    ) {
      return 'user';
    }
    return undefined;
  }

  // ─── Start / Stop ─────────────────────────────────────────

  /**
   * Start the camera with the given constraints.
   * Defaults to back camera (facingMode: 'environment') when no deviceId is given.
   */
  async start(constraints: CameraConstraints = {}): Promise<MediaStream> {
    // Check secure context first — on Samsung Internet / Chrome,
    // mediaDevices is undefined on insecure origins, which would
    // otherwise be mis-reported as "not supported".
    if (!CameraEngine.isSecureContext() || !CameraEngine.isSupported()) {
      const err = CameraEngine.buildUnavailableError();
      this.setState('error');
      this.emit('error', err);
      throw err;
    }

    // Stop any existing stream first
    await this.stop();

    this.setState('requesting');

    const mediaConstraints = this.buildMediaConstraints(constraints);

    try {
      logger.info('Requesting camera with constraints', mediaConstraints);
      const stream = await navigator.mediaDevices.getUserMedia(mediaConstraints);

      this.stream = stream;
      const videoTracks = stream.getVideoTracks();
      this.videoTrack = videoTracks[0] ?? null;

      if (!this.videoTrack) {
        stream.getTracks().forEach((t) => t.stop());
        this.stream = null;
        throw this.makeError('NotFoundError', 'No video track in the obtained stream');
      }

      this.currentDeviceId = this.videoTrack.getSettings().deviceId ?? null;

      // Listen for unexpected end
      this.videoTrack.addEventListener('ended', this.handleTrackEnded);

      this.setState('active');
      logger.info('Camera started', {
        deviceId: this.currentDeviceId,
        settings: this.videoTrack.getSettings(),
      });

      return stream;
    } catch (raw) {
      const err = this.normalizeError(raw);
      this.setState('error');
      this.emit('error', err);
      logger.error('Camera start failed', err);
      throw err;
    }
  }

  /** Stop the current stream and release the camera */
  async stop(): Promise<void> {
    if (this.videoTrack) {
      this.videoTrack.removeEventListener('ended', this.handleTrackEnded);
      this.videoTrack.stop();
      this.videoTrack = null;
    }
    if (this.stream) {
      this.stream.getTracks().forEach((t) => t.stop());
      this.stream = null;
    }
    this.currentDeviceId = null;
    if (this.state !== 'idle' && this.state !== 'stopped') {
      this.setState('stopped');
    }
    logger.info('Camera stopped');
  }

  private handleTrackEnded = (): void => {
    logger.warn('Video track ended unexpectedly');
    this.videoTrack = null;
    this.stream = null;
    this.currentDeviceId = null;
    this.setState('stopped');
    this.emit('trackended');
  };

  // ─── Switch camera ────────────────────────────────────────

  /**
   * Switch to another device while keeping similar constraints.
   */
  async switchDevice(deviceId: string, extra?: Partial<CameraConstraints>): Promise<MediaStream> {
    const currentSettings = this.videoTrack?.getSettings() ?? {};
    const constraints: CameraConstraints = {
      deviceId,
      width: currentSettings.width,
      height: currentSettings.height,
      frameRate: currentSettings.frameRate,
      ...extra,
    };
    return this.start(constraints);
  }

  /**
   * Prefer back camera. Falls back to any available camera.
   */
  async startBackCamera(extra?: Partial<CameraConstraints>): Promise<MediaStream> {
    return this.start({
      facingMode: 'environment',
      width: { ideal: 1280 },
      height: { ideal: 720 },
      frameRate: { ideal: 30 },
      ...extra,
    });
  }

  /**
   * Prefer front camera.
   */
  async startFrontCamera(extra?: Partial<CameraConstraints>): Promise<MediaStream> {
    return this.start({
      facingMode: 'user',
      width: { ideal: 1280 },
      height: { ideal: 720 },
      frameRate: { ideal: 30 },
      ...extra,
    });
  }

  // ─── Capabilities & settings ──────────────────────────────

  /** Get current track settings (resolution, frame rate, …) */
  getSettings(): MediaTrackSettings | null {
    return this.videoTrack?.getSettings() ?? null;
  }

  /** Get current resolution */
  getResolution(): CameraResolution | null {
    const s = this.getSettings();
    if (!s || s.width == null || s.height == null) return null;
    return { width: s.width, height: s.height };
  }

  /** Detect capabilities of the current (or given) track */
  async getCapabilities(deviceId?: string): Promise<CameraCapabilities | null> {
    // If we need capabilities of a different device, we may need a temporary stream
    if (deviceId && deviceId !== this.currentDeviceId) {
      // Best-effort: try to obtain a short-lived stream
      let tempStream: MediaStream | null = null;
      try {
        tempStream = await navigator.mediaDevices.getUserMedia({
          video: { deviceId: { exact: deviceId } },
          audio: false,
        });
        const track = tempStream.getVideoTracks()[0];
        if (!track) return null;
        return this.extractCapabilities(track);
      } catch {
        return null;
      } finally {
        tempStream?.getTracks().forEach((t) => t.stop());
      }
    }

    if (!this.videoTrack) return null;
    return this.extractCapabilities(this.videoTrack);
  }

  private extractCapabilities(track: MediaStreamTrack): CameraCapabilities {
    const caps = track.getCapabilities?.() ?? ({} as MediaTrackCapabilities);
    const settings = track.getSettings();

    return {
      deviceId: settings.deviceId ?? track.id,
      label: track.label,
      facingMode: Array.isArray(caps.facingMode)
        ? caps.facingMode[0]
        : (settings.facingMode as string | undefined),
      width: caps.width
        ? {
            min: caps.width.min,
            max: caps.width.max,
            // step is not part of the standard ULongRange type in TypeScript DOM libs
            step: (caps.width as { step?: number }).step,
          }
        : undefined,
      height: caps.height
        ? {
            min: caps.height.min,
            max: caps.height.max,
            step: (caps.height as { step?: number }).step,
          }
        : undefined,
      frameRate: caps.frameRate
        ? {
            min: caps.frameRate.min,
            max: caps.frameRate.max,
            step: (caps.frameRate as { step?: number }).step,
          }
        : undefined,
      torch: 'torch' in caps ? !!(caps as any).torch : undefined,
      zoom:
        'zoom' in caps && (caps as any).zoom
          ? {
              min: (caps as any).zoom.min,
              max: (caps as any).zoom.max,
              step: (caps as any).zoom.step,
            }
          : undefined,
      focusMode: Array.isArray((caps as any).focusMode) ? (caps as any).focusMode : undefined,
      exposureMode: Array.isArray((caps as any).exposureMode)
        ? (caps as any).exposureMode
        : undefined,
      raw: caps,
    };
  }

  // ─── Constraint builder ───────────────────────────────────

  private buildMediaConstraints(c: CameraConstraints): MediaStreamConstraints {
    const video: MediaTrackConstraints = {};

    if (c.deviceId) {
      video.deviceId = { exact: c.deviceId };
    } else if (c.facingMode) {
      video.facingMode = { ideal: c.facingMode };
    } else {
      // Default preference: back camera
      video.facingMode = { ideal: 'environment' };
    }

    if (c.width !== undefined) {
      video.width = typeof c.width === 'number' ? { ideal: c.width } : c.width;
    }
    if (c.height !== undefined) {
      video.height = typeof c.height === 'number' ? { ideal: c.height } : c.height;
    }
    if (c.frameRate !== undefined) {
      video.frameRate = typeof c.frameRate === 'number' ? { ideal: c.frameRate } : c.frameRate;
    }

    return { video, audio: false };
  }

  // ─── Error helpers ────────────────────────────────────────

  private makeError(code: CameraErrorCode, message: string, original?: unknown): CameraError {
    return { code, message, original };
  }

  private normalizeError(raw: unknown): CameraError {
    if (raw && typeof raw === 'object' && 'name' in raw) {
      const name = String((raw as DOMException).name);
      const message = String((raw as DOMException).message || name);

      const known: CameraErrorCode[] = [
        'NotAllowedError',
        'NotFoundError',
        'NotReadableError',
        'OverconstrainedError',
        'SecurityError',
        'AbortError',
        'TypeError',
      ];

      if (known.includes(name as CameraErrorCode)) {
        return this.makeError(name as CameraErrorCode, message, raw);
      }
    }

    return this.makeError(
      'UnknownError',
      raw instanceof Error ? raw.message : 'Unknown camera error',
      raw
    );
  }
}
